import{_ as t,o as e,c as o,a5 as a}from"./chunks/framework.BPFk9-tb.js";const m=JSON.parse('{"title":"写作课作业-097","description":"","frontmatter":{"date":"2020-10-26T09:01:46","title":"写作课作业-097","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/095.md","filePath":"posts/homework/095.md"}'),r={name:"posts/homework/095.md"};function s(_,p,n,c,i,d){return e(),o("div",null,[...p[0]||(p[0]=[a("<blockquote><p>10.24写作训练： 【在顶部写一句你自己想说的话】 【在下面尽可能的罗列能够表达同样意思的句子】 【穷尽各种可能】</p></blockquote><p>下飞机，上的士，过减速坎，司机一个油门，整个人往后一坐，说了句，你这是电车吧，真有力。</p><p>司机听了来劲，车转过弯来,到直路的时候，司机呼呼的踩着电门，我感觉有点的士速递的感觉。一路上我死死的抓住门把手。车呢，左摇右晃，时快时慢。但嘴上不能怂啊，司机开慢点是不能说出的，你还能快过飞机。</p><p>经过一段正在修路的路，过一个砍的时候，我整个人都被弹起来了，司机骂咧了一句，我说，看这路修的。</p><p>下车的时候，司机可能开得很爽，把车票都给撕坏了，他正在重打一张给我，我说不也能用么？他说，怕你不好报销。</p><p>其实我真想说， 师傅，你开慢点。</p><p>师傅，你开稳点。</p><p>师傅，你开太快啦。</p><p>师傅，我不急。</p><p>师傅，我们有时间。</p><p>师傅，你开车真稳。</p><hr><p>欢迎联系我</p><p>微信号 ：Crazy_Airhead</p><p>Mixin ID : 1091586</p><p>定投课堂邀请码：6DYMBFP061</p><p>李笑来写作课邀请码：38MDGFYZK8</p><p>水龙头邀请码：FDJQHJ</p>",18)])])}const f=t(r,[["render",s]]);export{m as __pageData,f as default};
